import { itemsLits } from "items";
import { cloneObj } from "utils";
import { GameScene } from "../modules";
import { gameConfig } from "game/config";

export class TestLocation extends GameScene {
  constructor() {
    super(
      [
        {
          image: [
            gameConfig.names.mainMapTile,
            "assets/locations/cloud_tileset.png",
          ],
          spritesheet: [
            "characters",
            "assets/locations/characters.png",
            { frameWidth: 52, frameHeight: 72 },
          ],
        },
        {
          image: ["extra", "assets/locations/extra.png"],
        },
      ],
      ["locationMap", "assets/locations/cloud_city.json"],
      {
        boxes: [
          {
            lock: 0,
            items: [
              //@ts-ignore
              { ...cloneObj(itemsLits.other[0]), amount: 5000 },
              //@ts-ignore
              { ...cloneObj(itemsLits.other[1]), amount: 966074 },
            ],
          },
          {
            lock: 15,
            items: [
              //@ts-ignore
              { ...cloneObj(itemsLits.other[1]), amount: 966074 },
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
              cloneObj(itemsLits.saturator[0]),
            ],
          },
        ],
        characters: {
          player: {
            sprite: "characters",
            startedPosition: { x: 30, y: 36 },
            scale: 1.5,
            id: "Player",
            type: "human",
          },
          enemy: {
            Monster: {
              id: "Monster",
              scale: 1.75,
              sprite: "characters",
              startedPosition: { x: 27, y: 37 },
              type: "monster",
            },
          },
          NPC: {},
        },
      },
    );
  }

  update(time: number, delta: number) {
    super.update(time, delta);
  }
}
